import React from 'react';
import { useTranslation } from 'react-i18next';
import { Menu, Transition } from '@headlessui/react';
import { CheckIcon, ChevronDownIcon } from '@heroicons/react/solid';
import classNames from 'classnames';

// Owner decision (2026-09): the switcher and the English option stay hidden
// until the new interface (filters, levels, banner) is translated. Set to true
// to bring back every switcher (top bar, phone menu, module sidebar, editor) and
// the stored choice (gatsby-browser.tsx).
export const LANGUAGE_SWITCHER_ENABLED = false;

const LANGUAGES = ['bg', 'en'];
// read back after hydration by gatsby-browser.tsx (onInitialClientRender)
export const LANGUAGE_STORAGE_KEY = 'olympiads:lang';
const LANGUAGE_LABELS = {
  bg: 'Български',
  en: 'English',
};

export default function LanguageDropdown({
  currentLanguage = 'bg',
  sidebarNav = false,
  onSelect = null as ((section: string) => void) | null,
  noDarkMode = false,
}): JSX.Element | null {
  const { i18n } = useTranslation();
  // the label follows i18next (useTranslation re-renders on a change), so every mounted switcher agrees after
  // a navigation; local state reset to Bulgarian while the interface stayed English
  const selectedLanguage = LANGUAGES.includes(i18n.language)
    ? i18n.language
    : currentLanguage;

  const changeLanguage = (lng: string) => {
    i18n.changeLanguage(lng);
    try {
      window.localStorage.setItem(LANGUAGE_STORAGE_KEY, lng);
    } catch (e) {
      // the choice just won't persist
    }
  };

  if (!LANGUAGE_SWITCHER_ENABLED) return null;

  return (
    <Menu as="div">
      {({ open }) => (
        <div className="relative h-full">
          <Menu.Button
            className={`group ${
              open || sidebarNav ? 'text-gray-900' : 'text-gray-500'
            } inline-flex items-center h-full space-x-2 text-base leading-6 font-medium hover:text-gray-900 focus:outline-none focus:text-gray-900 transition ease-in-out duration-150 ${
              !noDarkMode && `dark:text-dark-high-emphasis`
            }`}
          >
            <span>
              {LANGUAGE_LABELS[selectedLanguage]}
            </span>
            <ChevronDownIcon
              className={`${
                open ? 'text-gray-500' : 'text-gray-400'
              } h-5 w-5 group-hover:text-gray-500 group-focus:text-gray-500 transition ease-in-out duration-150 ${
                !noDarkMode &&
                'dark:text-dark-med-emphasis dark:group-hover:text-dark-med-emphasis dark:group-focus:text-dark-med-emphasis'
              }`}
              aria-hidden="true"
            />
          </Menu.Button>
          <Transition
            show={open}
            as={React.Fragment}
            enter="transition ease-out duration-100"
            enterFrom="transform opacity-0 scale-95"
            enterTo="transform opacity-100 scale-100"
            leave="transition ease-in duration-75"
            leaveFrom="transform opacity-100 scale-100"
            leaveTo="transform opacity-0 scale-95"
          >
            <Menu.Items
              static
              className={`origin-top-left absolute z-20 left-0 w-30 -ml-4 rounded-lg bg-white dark:bg-gray-800 ring-1 ring-black ring-opacity-5 shadow-lg focus:outline-none ${
                sidebarNav ? 'mt-2' : '-mt-2'
              }`}
            >
              <div className="py-1">
                {LANGUAGES.map(language => (
                  <Menu.Item key={language}>
                    {({ active }) => (
                      <button
                        onClick={() => changeLanguage(language)}
                        className={classNames(
                          'w-full text-left flex items-center justify-between gap-3 px-4 py-2 text-base font-medium leading-6 focus:outline-none',
                          active
                            ? 'bg-gray-100 text-gray-900 dark:text-gray-100 dark:bg-gray-700'
                            : 'text-gray-700 dark:text-gray-100'
                        )}
                        aria-current={
                          language === selectedLanguage ? 'true' : undefined
                        }
                      >
                        {LANGUAGE_LABELS[language]}
                        {language === selectedLanguage && (
                          <CheckIcon
                            className="h-5 w-5 text-blue-600 dark:text-blue-400"
                            aria-hidden="true"
                          />
                        )}
                      </button>
                    )}
                  </Menu.Item>
                ))}
              </div>
            </Menu.Items>
          </Transition>
        </div>
      )}
    </Menu>
  );
}
